+        /// <summary>
+        /// 构建包含解析 DevEntry 的退货项列表
+        /// </summary>
+        private List<dynamic> BuildReturnItemsWithDevEntry(List<dynamic> returnItems, Dictionary<int, int> resolvedDevEntryMap)
+        {
+            return returnItems.Select(x => new
+            {
+                x.DocEntry,
+                x.U_New_ORDRID,
+                x.ItemCode,
+                x.Price,
+                x.Quantity,
+                x.StockValue,
+                x.LastPurPrc,
+                x.CreateDate,
+                ResolvedDevEntry = GetResolvedDevEntry(x, resolvedDevEntryMap)
+            }).Where(x => x.ResolvedDevEntry > 0).ToList();
+        }
+
+        /// <summary>
+        /// 获取解析后的 DevEntry
+        /// </summary>
+        private int GetResolvedDevEntry(dynamic item, Dictionary<int, int> resolvedDevEntryMap)
+        {
+            var uDevEntry = item.U_DevEntry as string;
+            if (!string.IsNullOrEmpty(uDevEntry))
+            {
+                int.TryParse(uDevEntry, out var parsed);
+                return parsed;
+            }
+            if (item.DocEntry is int docEntry && resolvedDevEntryMap.TryGetValue(docEntry, out var resolved))
+            {
+                return resolved;
+            }
+            return 0;
+        }
+
+        /// <summary>
+        /// 尝试为指定订单创建罚息事件
+        /// </summary>
+        private PenaltyEventData TryCreatePenaltyEventForOrder(
+            int orderDocEntry,
+            IGrouping<int, dynamic> returnGroup,
+            ILookup<int, dynamic> delivrdProductsLookup,
+            List<dynamic> returnItemsWithDevEntry,
+            List<dynamic> delivrdItems,
+            string ruleId,
+            Dictionary<string, string> slpCodeToNameMap)
+        {
+            var thisOrdrReturnItems = BuildItemQtyMap(returnGroup, item => item.Quantity);
+            var delivrdItemsInThisOrdr = BuildItemQtyMap(delivrdProductsLookup[orderDocEntry], item => item.DelivrdQty);
+
+            if (!IsAllItemsReturnedItems(thisOrdrReturnItems, delivrdItemsInThisOrdr))
+            {
+                return null;
+            }
+
+            var returnedZeroPriceQtyByItem = BuildZeroPriceReturnedQtyMap(returnItemsWithDevEntry, orderDocEntry);
+            var fixedPenaltyAmount = CalculatePenaltyAmount(delivrdItems, orderDocEntry, returnedZeroPriceQtyByItem);
+
+            if (!fixedPenaltyAmount.HasValue || fixedPenaltyAmount == 0)
+            {
+                return null;
+            }
+
+            var slpCode = GetSalesPersonCode(delivrdItems, orderDocEntry);
+            var latestCreateDate = GetLatestCreateDate(returnGroup);
+
+            return new PenaltyEventData
+            {
+                RuleDefinitionId = ruleId,
+                SlpCode = slpCode,
+                SlpName = slpCodeToNameMap[slpCode.Value],
+                TriggerDocType = "ORDR",
+                TriggerDocEntry = orderDocEntry.ToString(),
+                SEDocEntry = orderDocEntry,
+                PenaltyBaseAmount = fixedPenaltyAmount.Value,
+                TriggerEventDate = latestCreateDate,
+                PenaltyStartDate = latestCreateDate
+            };
+        }
+
+        /// <summary>
+        /// 构建物料数量映射
+        /// </summary>
+        private Dictionary<string, decimal> BuildItemQtyMap(IEnumerable<dynamic> items, Func<dynamic, decimal> quantitySelector)
+        {
+            return items.GroupBy(x => x.ItemCode as string)
+                .Select(g => new { ItemCode = g.Key, TotalQty = g.Sum(s => quantitySelector(s)) })
+                .Where(x => x.ItemCode != null)
+                .ToDictionary(x => x.ItemCode, x => x.TotalQty);
+        }
+
+        /// <summary>
+        /// 检查所有有价物料是否已退完
+        /// </summary>
+        private bool IsAllItemsReturnedItems(Dictionary<string, decimal> thisOrdrReturnItems, Dictionary<string, decimal> delivrdItemsInThisOrdr)
+        {
+            return delivrdItemsInThisOrdr.All(x => x.Value == GetReturnedQty(thisOrdrReturnItems, x.Key));
+        }
+
+        /// <summary>
+        /// 获取已退数量
+        /// </summary>
+        private decimal GetReturnedQty(Dictionary<string, decimal> thisOrdrReturnItems, string itemCode)
+        {
+            return thisOrdrReturnItems.TryGetValue(itemCode, out var returnedQty) ? returnedQty : 0;
+        }
+
+        /// <summary>
+        /// 构建零价格物料已退数量映射
+        /// </summary>
+        private Dictionary<string, decimal> BuildZeroPriceReturnedQtyMap(List<dynamic> returnItemsWithDevEntry, int orderDocEntry)
+        {
+            return returnItemsWithDevEntry
+                .Where(x => (decimal)x.Price == 0 && (int)x.ResolvedDevEntry == orderDocEntry)
+                .GroupBy(x => x.ItemCode as string)
+                .Where(g => g.Key != null)
+                .ToDictionary(g => g.Key, g => g.Sum(s => s.Quantity));
+        }
+
+        /// <summary>
+        /// 计算罚息基础金额
+        /// </summary>
+        private decimal? CalculatePenaltyAmount(
+            List<dynamic> delivrdItems,
+            int orderDocEntry,
+            Dictionary<string, decimal> returnedZeroPriceQtyByItem)
+        {
+            return delivrdItems
+                .Where(x => (decimal)x.Price == 0 && (int)x.DocEntry == orderDocEntry)
+                .GroupBy(x => x.ItemCode as string)
+                .Where(g => g.Key != null)
+                .Sum(g => CalculateItemPenaltyAmount(g, returnedZeroPriceQtyByItem));
+        }
+
+        /// <summary>
+        /// 计算单个物料的罚息金额
+        /// </summary>
+        private decimal CalculateItemPenaltyAmount(IGrouping<string, dynamic> group, Dictionary<string, decimal> returnedZeroPriceQtyByItem)
+        {
+            var totalDelivrdQty = group.Sum(s => (decimal)s.DelivrdQty);
+            returnedZeroPriceQtyByItem.TryGetValue(group.Key, out var returnedQty);
+            var unreturnedQty = totalDelivrdQty - returnedQty;
+            return unreturnedQty > 0 ? unreturnedQty * (decimal)group.First().LastPurPrc : 0;
+        }
+
+        /// <summary>
+        /// 获取销售人员代码
+        /// </summary>
+        private int? GetSalesPersonCode(List<dynamic> delivrdItems, int orderDocEntry)
+        {
+            return delivrdItems.FirstOrDefault(x => (decimal)x.Price == 0 && (int)x.DocEntry == orderDocEntry)?.SlpCode;
+        }
+
+        /// <summary>
+        /// 获取最新的创建日期
+        /// </summary>
+        private DateTime GetLatestCreateDate(IGrouping<int, dynamic> group)
+        {
+            return group.OrderByDescending(x => x.CreateDate).First().CreateDate;
+        }

